#!/usr/bin/env bash
# Generates the files of the webrtc_src_oracle build in internal/webrtcoracle
# (all named src_gen_*):
#
#  - one translation unit per compiled WebRTC source file, which includes the
#    file from tmp_check/webrtc-m141 (src_gen_tu_*.cc/.c);
#  - the ec3 shim (ec3_shim.inc) under the two entry-point prefixes of
#    ec3_oracle.go.
#
#   scripts/gen-src-oracle.sh          regenerate
#   scripts/gen-src-oracle.sh -check   fail if the generated files are stale
set -euo pipefail

root=$(cd "$(dirname "$0")/.." && pwd)
pkg=$root/internal/webrtcoracle
src=$root/tmp_check/webrtc-m141
tag_plain='webrtc_src_oracle && !webrtc_oracle'

check=0
if [ "${1:-}" = "-check" ]; then
	check=1
fi

out=$(mktemp -d)
trap 'rm -rf "$out"' EXIT

# Sources compiled on every architecture.
aec3_avx2=(
	adaptive_fir_filter_avx2.cc
	adaptive_fir_filter_erl_avx2.cc
	fft_data_avx2.cc
	matched_filter_avx2.cc
	vector_math_avx2.cc
)
common_srcs=(
	api/audio/echo_canceller3_config.cc
	common_audio/audio_util.cc
	common_audio/channel_buffer.cc
	common_audio/resampler/push_sinc_resampler.cc
	common_audio/resampler/sinc_resampler.cc
	common_audio/signal_processing/splitting_filter.c
	common_audio/third_party/ooura/fft_size_128/ooura_fft.cc
	modules/audio_processing/audio_buffer.cc
	modules/audio_processing/high_pass_filter.cc
	modules/audio_processing/logging/apm_data_dumper.cc
	modules/audio_processing/splitting_filter.cc
	modules/audio_processing/three_band_filter_bank.cc
	modules/audio_processing/utility/cascaded_biquad_filter.cc
	rtc_base/checks.cc
	rtc_base/experiments/field_trial_parser.cc
	rtc_base/memory/aligned_malloc.cc
	rtc_base/race_checker.cc
	rtc_base/platform_thread_types.cc
	rtc_base/string_encode.cc
	rtc_base/string_to_number.cc
)
for f in "$src"/modules/audio_processing/aec3/*.cc; do
	b=$(basename "$f")
	case $b in
	*_unittest.cc | *_avx2.cc) continue ;;
	esac
	common_srcs+=("modules/audio_processing/aec3/$b")
done
# x86 only: SSE2 kernels in their own files, and the AVX2/FMA kernels
# (compiled with -mavx2 -mfma in libwebrtc's GN build).
x86_srcs=(
	common_audio/resampler/sinc_resampler_sse.cc
	common_audio/third_party/ooura/fft_size_128/ooura_fft_sse2.cc
)
x86_avx2_srcs=(common_audio/resampler/sinc_resampler_avx2.cc)
for b in "${aec3_avx2[@]}"; do
	x86_avx2_srcs+=("modules/audio_processing/aec3/$b")
done
# arm64 with NEON only.
neon_srcs=(
	common_audio/resampler/sinc_resampler_neon.cc
	common_audio/third_party/ooura/fft_size_128/ooura_fft_neon.cc
)

header() {
	printf '//go:build %s\n\n// Code generated by scripts/gen-src-oracle.sh. DO NOT EDIT.\n\n' "$1"
}

tu_name() {
	local p=${1%.*} ext=${1##*.}
	p=${p//\//_}
	echo "src_gen_tu_${p}.${ext}"
}

# emit_tu PATH CONSTRAINT [avx2]
emit_tu() {
	local path=$1 constraint=$2 avx2=${3:-}
	local f=$out/$(tu_name "$path")
	if [ ! -f "$src/$path" ]; then
		echo "gen-src-oracle: $src/$path is missing (run scripts/fetch-webrtc.sh)" >&2
		exit 1
	fi
	{
		header "$constraint"
		echo '#include "src_prelude.h"'
		echo
		if [ -n "$avx2" ]; then
			# libwebrtc compiles this file with -mavx2 -mfma. cgo cannot set
			# per-file flags, so its functions get the same target through a
			# pragma; the headers it includes come first so that only this
			# file's own functions are retargeted.
			grep '^#include' "$src/$path"
			echo
			echo '#pragma clang attribute push(__attribute__((target("avx2,fma"))), apply_to = function)'
			echo "#include \"../../tmp_check/webrtc-m141/$path\""
			echo '#pragma clang attribute pop'
		else
			echo "#include \"../../tmp_check/webrtc-m141/$path\""
		fi
	} >"$f"
}

for p in "${common_srcs[@]}"; do
	emit_tu "$p" "$tag_plain"
done
for p in "${x86_srcs[@]}"; do
	emit_tu "$p" "$tag_plain && amd64"
done
for p in "${x86_avx2_srcs[@]}"; do
	emit_tu "$p" "$tag_plain && amd64" avx2
done
for p in "${neon_srcs[@]}"; do
	emit_tu "$p" "$tag_plain && arm64 && !purego"
done

# The ec3 shim, once per entry-point prefix used by ec3_oracle.go: ec3_*
# (default) and ec3s_* (scalar). Both drive the one
# source build, whose lane follows the purego tag.
for prefix in ec3 ec3s; do
	{
		header "$tag_plain"
		echo '// The ec3 shim (ec3_shim.inc) over the source build.'
		echo '#include "src_prelude.h"'
		echo
		echo "#define EC3_FN(name) ${prefix}_##name"
		echo '#include "ec3_shim.inc"'
		echo
		if [ "$prefix" = ec3 ]; then
			echo 'extern "C" int ec3_config_num_fields(void) {'
			echo '  int n = 0;'
			echo '#define EC3_F(x) ++n;'
			echo '#include "ec3_config_fields.inc"'
			echo '#undef EC3_F'
			echo '  return n;'
			echo '}'
		fi
	} >"$out/src_gen_${prefix}_shim.cc"
done

if [ $check = 1 ]; then
	stale=0
	for f in "$out"/*; do
		if ! cmp -s "$f" "$pkg/$(basename "$f")"; then
			echo "gen-src-oracle: $(basename "$f") is stale" >&2
			stale=1
		fi
	done
	for f in "$pkg"/src_gen_*; do
		if [ ! -f "$out/$(basename "$f")" ]; then
			echo "gen-src-oracle: $(basename "$f") is no longer generated" >&2
			stale=1
		fi
	done
	if [ $stale = 1 ]; then
		echo "gen-src-oracle: run scripts/gen-src-oracle.sh" >&2
		exit 1
	fi
	exit 0
fi

rm -f "$pkg"/src_gen_*
cp "$out"/* "$pkg"/
echo "gen-src-oracle: wrote $(ls "$out" | wc -l | tr -d ' ') files"
